do $d$ declare s text; n text; begin s := pg_get_functiondef('public.finalize_job_gp(uuid)'::regprocedure); n := replace(s, 'values (p_job, v_seq, f.net_contract, f.client_received', 'values (p_job, v_seq, f.contract_amount, f.client_received'); n := replace(n, 'if coalesce(f.net_contract, 0) <= 0 then', 'if coalesce(f.contract_amount, 0) <= 0 then'); if n = s then raise exception 'finalize: no match'; end if; execute n; s := pg_get_functiondef('public.report_monthly_scorecard'::regproc); n := replace(s, 'from public.client_payments cp where payment_date is not null and not coalesce((select pt.is_credit from public.payment_types pt where pt.key = cp.payment_type), false))', 'from public.client_payments where payment_date is not null)'); n := replace(n, 'jf.net_contract rev,', 'jf.contract_amount rev,'); n := replace(n, '(select coalesce(sum(jf2.net_contract), 0) from comp c join live l on l.id = c.job_id join public.job_financials jf2 on jf2.job_id = l.id where', '(select coalesce(sum(l.contract_amount), 0) from comp c join live l on l.id = c.job_id where'); if (length(s) - length(n)) < 150 then raise exception 'scorecard revert incomplete (%)', length(s) - length(n); end if; execute n; s := pg_get_functiondef('public.report_balances_owed'::regproc); n := replace(s, 'td as (select cp.job_id, sum(cp.amount) filter (where not coalesce(pt.is_credit, false)) paid, max(cp.payment_date) filter (where not coalesce(pt.is_credit, false)) last_paid, count(*) filter (where not coalesce(pt.is_credit, false)) n, sum(cp.amount) filter (where pt.is_credit) credits from public.client_payments cp left join public.payment_types pt on pt.key = cp.payment_type group by cp.job_id)', 'td as (select job_id, sum(amount) paid, max(payment_date) last_paid, count(*) n from public.client_payments group by job_id), cr as (select job_id, sum(amount) credited, count(*) n from public.client_credits group by job_id)'); n := replace(n, 'coalesce(l.contract_amount, 0) - coalesce(td.credits, 0) contract, coalesce(td.credits, 0) credits,', 'coalesce(l.contract_amount, 0) contract, coalesce(cr.credited, 0) client_credited, coalesce(cr.n, 0) client_credits_count,'); n := replace(n, 'left join td on td.job_id = l.id', 'left join td on td.job_id = l.id left join cr on cr.job_id = l.id'); n := replace(n, '''balance'', x.contract - x.collected,', '''balance'', x.contract - x.collected - x.client_credited,'); n := replace(n, 'order by (x.contract - x.collected) desc', 'order by (x.contract - x.collected - x.client_credited) desc'); execute n; end $d$;;
